// 송예찬 V0.01. Editor-only model import and scene structure; no runtime movement logic.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1StructureApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static string Src=>Repo+"/SourceAssets/F1_RoofLiftWilderness/";
 static Dictionary<string,Material> mats=new Dictionary<string,Material>();
 static void Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");}
 static void Load(){mats.Clear();foreach(var p in Directory.GetFiles(E+"Materials","AE_M_*.mat")){var m=AssetDatabase.LoadAssetAtPath<Material>(p.Replace('\\','/'));mats[m.name]=m;}}
 public static object Import(){Check();Load();var candidate=Path.Combine(Path.GetTempPath(),"AfterSeconds_20261113/candidate");var all=JArray.Parse(File.ReadAllText(Src+"roof_models.json")).Concat(JArray.Parse(File.ReadAllText(Src+"detail_models.json"))).ToArray();
 foreach(var q in all){string n=(string)q["name"],path=E+n+".fbx";File.Copy(Path.Combine(candidate,n+".fbx"),path,true);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(ModelImporter)AssetImporter.GetAtPath(path);imp.importCameras=false;imp.importLights=false;imp.importAnimation=false;imp.isReadable=false;imp.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;imp.materialLocation=ModelImporterMaterialLocation.InPrefab;foreach(string mat in q["materials"].Select(v=>(string)v)){if(!mats.ContainsKey(mat))throw new Exception("Unknown material "+mat);imp.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),mat),mats[mat]);}imp.SaveAndReimport();}
 // Retain original prefab instances/GUIDs, update explicitly overridden renderer slots.
 foreach(var q in all.Where(q=>((string)q["name"]).StartsWith("AE_"))){string n=(string)q["name"];var g=GameObject.Find(n);if(!g)throw new Exception("Missing scene roof "+n);var proto=AssetDatabase.LoadAssetAtPath<GameObject>(E+n+".fbx");var mesh=proto.GetComponentInChildren<MeshFilter>().sharedMesh;var materials=proto.GetComponentInChildren<Renderer>().sharedMaterials;foreach(var f in g.GetComponentsInChildren<MeshFilter>()){f.sharedMesh=mesh;f.GetComponent<Renderer>().sharedMaterials=materials;var col=f.GetComponent<MeshCollider>();if(col)col.sharedMesh=mesh;Record(f.gameObject);}}
 Save();return new{imported=all.Length};}
 static void Record(GameObject g){foreach(var c in g.GetComponents<Component>())if(c&&PrefabUtility.IsPartOfPrefabInstance(c))PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
 static GameObject Group(string name,Transform parent,Vector3 local){var g=new GameObject(name);g.transform.SetParent(parent,false);g.transform.localPosition=local;return g;}
 static GameObject Model(string asset,string name,Transform parent,Vector3 local,bool collision=true,bool moving=false){var p=AssetDatabase.LoadAssetAtPath<GameObject>(E+asset+".fbx");if(!p)throw new Exception(asset);var g=(GameObject)PrefabUtility.InstantiatePrefab(p,parent);g.name=name;g.transform.localPosition=local;foreach(var f in g.GetComponentsInChildren<MeshFilter>()){if(collision)f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;GameObjectUtility.SetStaticEditorFlags(f.gameObject,moving?0:StaticEditorFlags.ReflectionProbeStatic|StaticEditorFlags.OccludeeStatic);}Record(g);return g;}
 static void Clear(GameObject g){if(PrefabUtility.IsPartOfPrefabInstance(g))PrefabUtility.UnpackPrefabInstance(g,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);foreach(var t in g.transform.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);foreach(var c in g.GetComponents<Component>().Where(c=>!(c is Transform)).ToArray())UnityEngine.Object.DestroyImmediate(c);}
 static void Anchor(string n,Transform p,Vector3 v)=>Group(n,p,v);
 static void Save(){var s=SceneManager.GetActiveScene();Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);}
 public static object Build(){Check();Load();var root=GameObject.Find("1F_AbandonedFactory");if(root.transform.Find("1F_VL/F1_VL_LiftAssembly"))throw new Exception("Already built; use scoped fixes");
 var vl=root.transform.Find("1F_VL");var old=vl.Find("F1_VL_LiftCabin_01").gameObject;Clear(old);old.name="F1_VL_LiftAssembly";old.transform.position=new Vector3(44,0,29);var fixedRoot=Group("FixedShaft",old.transform,Vector3.zero).transform;Model("FW_LiftShaft","ShaftShell",fixedRoot,Vector3.zero);Model("FW_LiftGuides","GuideRailsAndBuffers",fixedRoot,Vector3.zero);Model("FW_LiftLanding","LandingFrameAndSill",fixedRoot,Vector3.zero);Model("FW_LiftHoist","MachineBedMotorBrake",fixedRoot,Vector3.zero,false);
 var car=Group("Car",old.transform,new Vector3(0,0,-.6f)).transform;Model("FW_LiftCar","CarBodyAndSling",car,Vector3.zero,true,true);Model("FW_LiftDoorLeft","DoorLeft",car,new Vector3(-1.98f,0,-1.78f),true,true);Model("FW_LiftDoorRight","DoorRight",car,new Vector3(1.98f,0,-1.78f),true,true);Anchor("RopeAttachment",car,new Vector3(0,3.79f,0));Anchor("FloorLevel",car,new Vector3(0,.075f,0));
 var cw=Group("Counterweight",old.transform,new Vector3(-2.4f,-17.2f,-.6f)).transform;Model("FW_LiftCounterweight","CounterweightFrameAndBlocks",cw,Vector3.zero,true,true);Anchor("RopeAttachment",cw,new Vector3(0,2.96f,0));
 var sh=Group("Sheave",old.transform,new Vector3(-1.2f,4.8f,-.6f)).transform;Model("FW_LiftSheave","GroovedWheel",sh,Vector3.zero,false,true);Anchor("Axle_Z",sh,Vector3.zero);
 var ropes=Group("Ropes",old.transform,Vector3.zero).transform;Model("FW_LiftRopeArc","FixedWrap",ropes,new Vector3(-1.2f,4.8f,-.6f),false,true);var r1=Model("FW_LiftRopeDrop","ToCar",ropes,new Vector3(0,4.8f,-.6f),false,true);r1.transform.localScale=new Vector3(1,1.01f,1);Record(r1);var r2=Model("FW_LiftRopeDrop","ToCounterweight",ropes,new Vector3(-2.4f,4.8f,-.6f),false,true);r2.transform.localScale=new Vector3(1,19.04f,1);Record(r2);
 Anchor("Stop_1F",old.transform,new Vector3(0,0,-.6f));Anchor("Stop_B1",old.transform,new Vector3(0,-18,-.6f));
 // Landing doors stay attached to fixed shaft; separate from cabin doors.
 Model("FW_LiftDoorLeft","LandingDoorLeft",fixedRoot,new Vector3(-1.98f,0,-2.86f),true,true);Model("FW_LiftDoorRight","LandingDoorRight",fixedRoot,new Vector3(1.98f,0,-2.86f),true,true);
 var vb=root.transform.Find("1F_VB");var door=vb.Find("F1_VB_ArrivalFireDoor_01").gameObject;Clear(door);door.transform.position=new Vector3(44,0,-31.1f);Model("FW_VBDoorFrame","Frame",door.transform,Vector3.zero);var dl=Group("DoorLeftPivot",door.transform,new Vector3(-.97f,0,0)).transform;dl.localRotation=Quaternion.Euler(0,-100,0);Model("FW_VBDoorLeft","Leaf",dl,Vector3.zero,true,true);var dr=Group("DoorRightPivot",door.transform,new Vector3(.97f,0,0)).transform;dr.localRotation=Quaternion.Euler(0,100,0);Model("FW_VBDoorRight","Leaf",dr,Vector3.zero,true,true);
 var stairs=Group("F1_VB_StairConnection",vb,new Vector3(44,0,-28)).transform;Model("FW_VBShaft","StairwellAndGuardrails",stairs,Vector3.zero);
 string b1="Assets/Afrer_Seconds/05.Model/Environment/B1/BL_Stairs18m.fbx";var st=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(b1),stairs);st.name="B1To1F_Stairs18m";st.transform.localPosition=new Vector3(0,-18,0);foreach(var mf in st.GetComponentsInChildren<MeshFilter>()){mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;var rr=mf.GetComponent<Renderer>();rr.sharedMaterials=rr.sharedMaterials.Select(m=>mats.ContainsKey("AE_M_"+m.name.Split('_').Last())?mats["AE_M_"+m.name.Split('_').Last()]:mats["AE_M_Steel"]).ToArray();Record(mf.gameObject);}Record(st);Anchor("ArrivalLanding_1F",stairs,new Vector3(0,0,-2.32f));Anchor("Arrival_B1",stairs,new Vector3(0,-18,-2.32f));
 for(int i=0;i<4;i++){var g=Group("StairwellBounce_"+i,stairs,new Vector3(0,-1.5f-i*4.5f,-.5f));var light=g.AddComponent<Light>();light.type=LightType.Point;light.range=7;light.intensity=.65f;light.color=new Color(.62f,.68f,.74f);light.shadows=LightShadows.None;}
 Save();return new{liftRoot=old.name,car=car.name,staircase=b1,gameplayScriptsAdded=0};}
}
